-- Seed generated from public/concepts.json and public/videos.json. Idempotent.

insert into public.concepts (id, name, parent_id, summary, sort_order)
select c->>'id', c->>'name', c->>'parentId', c->>'summary', (c->>'order')::int
from jsonb_array_elements($cpack$[{"id":"fundamentals","name":"System Fundamentals","parentId":null,"summary":"Core building blocks of distributed systems, including performance metrics, scalability patterns, and foundational infrastructure components.","order":1},{"id":"data","name":"Data & Storage","parentId":null,"summary":"Databases, replication, sharding, consistency models, durability, and concurrency control strategies for managing data at scale.","order":2},{"id":"async","name":"Async & Reliability","parentId":null,"summary":"Message queues, stream processing, reliability engineering, and observability primitives for building resilient distributed systems.","order":3},{"id":"ai-systems","name":"AI Systems","parentId":null,"summary":"Machine learning infrastructure covering embeddings, retrieval, LLM inference, agentic systems, and model evaluation.","order":4},{"id":"latency-metrics","name":"Latency & Metrics","parentId":"fundamentals","summary":"Percentile latency (p50/p95/p99), SLOs, SLAs, and the techniques used to measure and reduce tail latency in distributed services.","order":1},{"id":"scalability","name":"Scalability","parentId":"fundamentals","summary":"Horizontal vs. vertical scaling, stateless design, auto-scaling policies, and the capacity-planning approaches that let systems handle growing load.","order":2},{"id":"load-balancing","name":"Load Balancing","parentId":"fundamentals","summary":"Round-robin, least-connections, consistent hashing, and health-check strategies that distribute traffic across server fleets without hot spots.","order":3},{"id":"caching","name":"Caching","parentId":"fundamentals","summary":"In-process, distributed (Redis/Memcached), and CDN caching layers; eviction policies (LRU, LFU), cache stampede prevention, and write-through vs. write-behind patterns.","order":4},{"id":"cdn","name":"CDN","parentId":"fundamentals","summary":"Content delivery networks that serve static and dynamic assets from edge PoPs, reducing origin load and cutting cross-region latency for end users.","order":5},{"id":"api-design","name":"API Design","parentId":"fundamentals","summary":"REST, GraphQL, and gRPC API design principles including versioning, idempotency, pagination, and error-handling conventions for public-facing services.","order":6},{"id":"rate-limiting","name":"Rate Limiting","parentId":"fundamentals","summary":"Token bucket, leaky bucket, sliding window, and fixed window algorithms that enforce per-client quotas to protect services from abuse and overload.","order":7},{"id":"databases","name":"Databases","parentId":"data","summary":"Relational (PostgreSQL, MySQL) and NoSQL (DynamoDB, Cassandra, MongoDB) database fundamentals, indexing strategies, and query optimisation.","order":1},{"id":"replication","name":"Replication","parentId":"data","summary":"Leader-follower and multi-leader replication, replication lag, read replicas, and failover mechanisms that keep data available when nodes fail.","order":2},{"id":"sharding","name":"Sharding","parentId":"data","summary":"Horizontal data partitioning by key range, hash, or directory; consistent hashing rings; and re-sharding strategies for growing data sets.","order":3},{"id":"consistency","name":"Consistency","parentId":"data","summary":"CAP theorem, eventual vs. strong vs. causal consistency, linearisability, and the practical trade-offs between read freshness and availability.","order":4},{"id":"durability","name":"Durability","parentId":"data","summary":"Write-ahead logging (WAL), checkpointing, RAID, cross-region backups, and RPO/RTO targets that determine how much data loss a system can tolerate.","order":5},{"id":"concurrency","name":"Concurrency Control","parentId":"data","summary":"Optimistic and pessimistic locking, MVCC, two-phase locking, and distributed transactions (2PC, Saga) for coordinating concurrent writes.","order":6},{"id":"queues","name":"Message Queues","parentId":"async","summary":"Point-to-point and pub/sub messaging with RabbitMQ, SQS, and Kafka; dead-letter queues, acknowledgement semantics, and at-least-once delivery guarantees.","order":1},{"id":"stream-processing","name":"Stream Processing","parentId":"async","summary":"Real-time event processing with Kafka Streams, Flink, and Spark Streaming; windowing, watermarking, and exactly-once semantics.","order":2},{"id":"reliability","name":"Reliability Engineering","parentId":"async","summary":"Retry policies, circuit breakers, timeouts, bulkheads, and chaos engineering practices that make services recover gracefully from failures.","order":3},{"id":"observability","name":"Observability","parentId":"async","summary":"The three pillars—metrics, logs, and distributed traces—and the tooling (Prometheus, Grafana, OpenTelemetry, Jaeger) used to understand system behaviour.","order":4},{"id":"embeddings-vector-search","name":"Embeddings & Vector Search","parentId":"ai-systems","summary":"Dense vector representations of text, images, and code; ANN indexing (HNSW, IVF); and hybrid BM25 + dense retrieval with reciprocal rank fusion.","order":1},{"id":"rag","name":"Retrieval-Augmented Generation","parentId":"ai-systems","summary":"Architecture patterns for grounding LLM responses in retrieved documents: chunking, indexing, re-ranking, query rewriting, and quality evaluation.","order":2},{"id":"llm-inference","name":"LLM Inference","parentId":"ai-systems","summary":"Serving large language models efficiently: continuous batching, KV-cache management, quantisation, speculative decoding, and disaggregated prefill/decode.","order":3},{"id":"agents","name":"Agentic Systems","parentId":"ai-systems","summary":"LLM-powered agents with tools, memory, and planning; multi-agent orchestration; loop prevention; and evaluation frameworks for long-horizon tasks.","order":4},{"id":"fine-tuning","name":"Fine-tuning","parentId":"ai-systems","summary":"Parameter-efficient fine-tuning (LoRA, QLoRA), full fine-tuning, dataset curation, catastrophic forgetting mitigation, and trade-offs with in-context learning.","order":5},{"id":"evaluation","name":"Evaluation","parentId":"ai-systems","summary":"Benchmark design, LLM-as-judge, RAGAS, human evaluation, A/B testing, and the metrics used to compare model and system quality objectively.","order":6},{"id":"multimodal","name":"Multimodal Systems","parentId":"ai-systems","summary":"Unified and late-fusion architectures for text, image, audio, and video; ColPali document retrieval; VLMs for generation; and multimodal evaluation.","order":7}]$cpack$::jsonb) as t(c)
on conflict (id) do update set
  name = excluded.name, parent_id = excluded.parent_id,
  summary = excluded.summary, sort_order = excluded.sort_order;

insert into public.videos (id, youtube_id, title, channel, level, summary, concepts, sort_order)
select v->>'id', v->>'youtubeId', v->>'title', v->>'channel', v->>'level',
  v->>'summary', array(select jsonb_array_elements_text(v->'concepts')), (ord - 1)::int
from jsonb_array_elements($vpack$[{"id":"gs-system-primer","youtubeId":"SqcXvc3ZmRU","title":"System Design Primer ⭐️: How to start with distributed systems?","channel":"Gaurav Sen","level":"beginner","concepts":["scalability","latency-metrics"],"summary":"Gaurav Sen lays out a roadmap for learning distributed systems, explaining what scalability means and why you must reason about it before designing anything."},{"id":"gs-horiz-vert-scaling","youtubeId":"xpDnVSmNFX0","title":"System Design BASICS: Horizontal vs. Vertical Scaling","channel":"Gaurav Sen","level":"beginner","concepts":["scalability"],"summary":"Clear comparison of adding more CPUs/RAM to one machine (vertical) versus adding more machines (horizontal), with trade-offs for each approach."},{"id":"gs-load-balancing","youtubeId":"K0Ta65OqQkY","title":"What is LOAD BALANCING? ⚖️","channel":"Gaurav Sen","level":"beginner","concepts":["load-balancing"],"summary":"Introduces load balancers, explains round-robin and least-connections strategies, and walks through why they are critical for availability."},{"id":"gs-consistent-hashing","youtubeId":"zaRkONvyGr8","title":"What is CONSISTENT HASHING and Where is it used?","channel":"Gaurav Sen","level":"beginner","concepts":["load-balancing","sharding"],"summary":"Explains the problem with naive modulo hashing when nodes change, then introduces the ring-based consistent hashing solution with virtual nodes."},{"id":"bbg-algorithms-sd","youtubeId":"xbgzl2maQUU","title":"Algorithms You Should Know Before System Design Interviews","channel":"ByteByteGo","level":"beginner","concepts":["scalability","caching","sharding"],"summary":"ByteByteGo surveys the key algorithms behind system design—consistent hashing, bloom filters, Merkle trees, and more—with animated diagrams."},{"id":"hn-btree-database","youtubeId":"UzHl2VzyZS4","title":"B-tree vs B+ tree in Database Systems","channel":"Hussein Nasser","level":"beginner","concepts":["databases"],"summary":"Hussein Nasser compares B-tree and B+ tree structures, explaining how they differ in storage of data pointers and why B+ trees dominate relational database indexes."},{"id":"hn-kafka-intro","youtubeId":"LN_HcJVbySw","title":"What is Kafka and How does it work?","channel":"Hussein Nasser","level":"beginner","concepts":["queues","stream-processing"],"summary":"A beginner-friendly breakdown of Apache Kafka covering topics, partitions, producers, consumers, and consumer groups with real examples."},{"id":"hn-nginx-crash","youtubeId":"hcw-NjOh8r0","title":"NginX Crash Course","channel":"Hussein Nasser","level":"beginner","concepts":["load-balancing","cdn"],"summary":"Covers how NGINX works as both a web server and reverse proxy, including configuration for load balancing, TLS termination, and caching static assets."},{"id":"jhnl-db-indexes","youtubeId":"LzNdvuj3a5M","title":"Database Indexes: What do they do? | Systems Design Interview: 0 to 1 with Google Software Engineer","channel":"Jordan has no life","level":"beginner","concepts":["databases"],"summary":"Walks through what a database index is, how B-tree and hash indexes work, and the trade-offs between read performance and write overhead."},{"id":"assemblyai-vector-dbs","youtubeId":"dN0lsF2cvm4","title":"Vector Databases simply explained! (Embeddings & Indexes)","channel":"AssemblyAI","level":"beginner","concepts":["embeddings-vector-search"],"summary":"Explains vector embeddings and how vector databases store and search high-dimensional data using ANN indexes such as HNSW."},{"id":"hi-rate-limiter","youtubeId":"MIJFyUPG4Z4","title":"Design a Distributed Rate Limiter w/ a Ex-Meta Staff Engineer: System Design Breakdown","channel":"Hello Interview","level":"beginner","concepts":["rate-limiting"],"summary":"A Meta staff engineer walks through designing a distributed rate limiter, covering token bucket, sliding window log, Redis-based counters, and multi-region concerns."},{"id":"hi-message-queues","youtubeId":"1ISRd0bS714","title":"Message Queues in System Design Interviews w/ Meta Staff Engineer","channel":"Hello Interview","level":"beginner","concepts":["queues"],"summary":"Explains when and how to introduce a message queue in a system design interview, including fan-out patterns, backpressure, and durability guarantees."},{"id":"bbg-consistent-hashing","youtubeId":"UF9Iqmg94tk","title":"Consistent Hashing | Algorithms You Should Know #1","channel":"ByteByteGo","level":"intermediate","concepts":["sharding","load-balancing"],"summary":"ByteByteGo visualizes consistent hashing with virtual nodes, showing exactly how requests are routed and how node additions or removals minimize key remapping."},{"id":"bbg-kafka-fast","youtubeId":"UNUz1-msbOM","title":"System Design: Why is Kafka fast?","channel":"ByteByteGo","level":"intermediate","concepts":["stream-processing","queues"],"summary":"Dives into the design choices that make Kafka extremely fast: sequential disk I/O, zero-copy data transfer, and batched compression of messages."},{"id":"bbg-kafka-3min","youtubeId":"HZklgPkboro","title":"System Design: Apache Kafka In 3 Minutes","channel":"ByteByteGo","level":"intermediate","concepts":["queues","stream-processing"],"summary":"A rapid animated overview of Kafka architecture—brokers, topics, partitions, replication, and consumer groups—ideal for a quick refresher before an interview."},{"id":"hn-db-replication","youtubeId":"aE2UPg3Ckck","title":"All Types of Database Replication Discussed","channel":"Hussein Nasser","level":"intermediate","concepts":["replication","consistency"],"summary":"Hussein Nasser surveys synchronous, asynchronous, logical, and streaming replication, explaining the consistency vs. performance trade-offs for each mode."},{"id":"hn-acid","youtubeId":"QCKZ3VZ87Qo","title":"Database ACID - Live Stream (by Hussein Nasser)","channel":"Hussein Nasser","level":"intermediate","concepts":["durability","consistency","databases"],"summary":"A deep-dive into ACID properties—atomicity, consistency, isolation, and durability—showing how relational databases implement each guarantee with real SQL examples."},{"id":"sdfc-youtube-sd","youtubeId":"ghYbFgeqXa0","title":"System Design: YouTube (with FAANG Senior Engineer)","channel":"System Design Fight Club","level":"intermediate","concepts":["cdn","caching","scalability"],"summary":"A FAANG senior engineer designs a YouTube-like video platform, covering upload pipelines, transcoding, CDN edge caching, and recommendation feed scaling."},{"id":"sdfc-rate-limiter","youtubeId":"NvQXO7tleDI","title":"Atlassian Interview Question | System Design: Rate Limiter (5+ Approaches)","channel":"System Design Fight Club","level":"intermediate","concepts":["rate-limiting","consistency"],"summary":"Explores five distinct rate-limiter designs—in-process, Redis-based, sliding window, token bucket, and distributed—weighing each for a real Atlassian interview scenario."},{"id":"jhnl-dropbox-sd","youtubeId":"4wIU4rTV-JU","title":"3: Dropbox + Google Drive | Systems Design Interview Questions With Ex-Google SWE","channel":"Jordan has no life","level":"intermediate","concepts":["databases","sharding","cdn"],"summary":"Designs a cloud storage service from scratch, addressing block-level deduplication, metadata storage sharding, sync conflict resolution, and CDN-based delivery."},{"id":"hi-design-leetcode","youtubeId":"1xHADtekTNg","title":"System Design Interview: Design LeetCode (Online Judge) w/ a Ex-Meta Staff Engineer","channel":"Hello Interview","level":"intermediate","concepts":["databases","caching","api-design"],"summary":"Step-by-step design of an online judge system, covering problem and submission storage, distributed code execution sandboxes, and result caching."},{"id":"anyscale-rag-scale","youtubeId":"uTz7Jyunb98","title":"Why RAG Breaks at Scale | Anyscale Webinar","channel":"Anyscale","level":"intermediate","concepts":["rag","embeddings-vector-search"],"summary":"Anyscale engineers diagnose where RAG pipelines fail under production scale, covering chunking strategies, embedding drift, retrieval precision, and async data pipelines."},{"id":"pragmatic-vector-arch","youtubeId":"3y_7fE5Ftaw","title":"Vector Database Architecture Explained","channel":"Pragmatic AI Labs","level":"intermediate","concepts":["embeddings-vector-search"],"summary":"A thorough walkthrough of vector database internals—HNSW graphs, IVF indexes, quantization, and the trade-offs between recall, latency, and storage."},{"id":"sdfc-fb-messenger","youtubeId":"Pq5Iy0FGYMM","title":"System Design: Facebook Messenger (5+ approaches)","channel":"System Design Fight Club","level":"intermediate","concepts":["queues","sharding","consistency"],"summary":"A FAANG senior engineer presents five different chat backend architectures, from simple pub-sub to fan-out-on-read vs. write, with explicit trade-off analysis."},{"id":"hi-design-tinder","youtubeId":"18Fg5Akhkqw","title":"System Design Interview: Design Tinder w/ a Ex-Meta Staff Engineer","channel":"Hello Interview","level":"advanced","concepts":["sharding","databases","caching","scalability"],"summary":"Deep-dive into a geo-distributed matching service, covering profile storage sharding, geohash-based proximity search, recommendation ranking, and swipe-storm traffic shaping."},{"id":"jhnl-netflix-youtube","youtubeId":"43bB7oSn190","title":"5: Netflix + YouTube | Systems Design Interview Questions With Ex-Google SWE","channel":"Jordan has no life","level":"advanced","concepts":["cdn","replication","stream-processing"],"summary":"Designs a large-scale video streaming service covering adaptive bitrate streaming, CDN placement strategy, view-count aggregation pipelines, and multi-region replication."},{"id":"anyscale-vllm-rise","youtubeId":"WLl8D1nyaW8","title":"The Rise of vLLM: Building an Open Source LLM Inference Engine","channel":"Anyscale","level":"advanced","concepts":["llm-inference"],"summary":"The vLLM team traces the design of PagedAttention and continuous batching that made vLLM the dominant open-source LLM serving engine, with throughput benchmarks."},{"id":"anyscale-model-serving","youtubeId":"LKUBwGTUDZE","title":"Faster Model Serving with Ray and Anyscale | Ray Summit 2024","channel":"Anyscale","level":"advanced","concepts":["llm-inference","scalability"],"summary":"Covers Ray Serve’s autoscaling, request batching, and multi-GPU deployment patterns for production LLM inference, with cost and latency benchmarks."},{"id":"anyscale-llm-platform","youtubeId":"ciJY7JAWzi8","title":"Anyscale’s Unified Platform for LLM Development and Deployment | Ray Summit 2024","channel":"Anyscale","level":"advanced","concepts":["llm-inference","agents","rag"],"summary":"Presents Anyscale’s end-to-end platform for LLM workflows—training, fine-tuning, RAG pipelines, agentic orchestration, and production serving—on Ray."},{"id":"anyscale-ray-serve","youtubeId":"TJ5K1CO9Wbs","title":"Enabling Cost-Efficient LLM Serving with Ray Serve","channel":"Anyscale","level":"advanced","concepts":["llm-inference","scalability"],"summary":"Shows how Ray Serve’s fractional GPU sharing, replica autoscaling, and request routing reduce LLM serving cost significantly versus naive single-model deployments."}]$vpack$::jsonb) with ordinality as t(v, ord)
on conflict (id) do update set
  youtube_id = excluded.youtube_id, title = excluded.title, channel = excluded.channel,
  level = excluded.level, summary = excluded.summary, concepts = excluded.concepts,
  sort_order = excluded.sort_order;
